LOG_STATE_FILE = LOG_DIR / "master_log_state.json"
RESET_HOURS = 72
RUN_ID = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
GIT_SHA = os.getenv("GITHUB_SHA", "local")
