    low = title.lower()
    bad_patterns = [
        "stella ufc",
        "rivelatrice",
        "odato",
        "odate",
        "prevalenza",
    ]
    if any(p in low for p in bad_patterns):
        return True
    if len(title) > 95:
        return True
    return False


