# =========================
# v80.8: follow-up dedupe startup fix
# =========================
# Fix mirata: stesso wrestler + stesso evento non deve bastare per bloccare
# articoli che cambiano l'angolo editoriale. Esempi: backstage reaction,
# uncertainty about future, semi-retired/retirement/career-status follow-up.
# Rispetto alla v80.7, l'entrypoint e' spostato dopo gli override, quindi
# la patch e' effettivamente attiva durante la run.
# Non tocca scoring, spoiler, traduzione, AAA, report o review packages.

BOT_VERSION = "v80_8_followup_dedupe_startup_fix"
BOT_VERSION_FULL = f"{BOT_VERSION} ({GIT_SHA_SHORT})"

_ORIG_V807_v7915_stable_story_key = v7915_stable_story_key
_ORIG_V807_build_story_signature_v71 = build_story_signature_v71
_ORIG_V807_semantic_duplicate_check_v71 = semantic_duplicate_check_v71

V807_FOLLOWUP_ADVANCEMENT_TERMS = [
    "backstage reaction", "backstage reactions", "reaction backstage", "reactions backstage",
    "uncertainty about her future", "uncertainty about his future", "uncertainty about their future",
    "uncertain future", "future uncertain", "future with wwe", "future in wwe", "wwe future",
    "semi retired", "semi-retired", "part time", "part-time", "retirement", "retired",
    "career status", "status with wwe", "status in wwe", "future status",
]


def v807_is_followup_advancement_title(title="", text=""):
    """True se il titolo indica un nuovo angolo editoriale, non un semplice rewrite.

    Regola volutamente stretta: usiamo soprattutto il titolo, per evitare che parole
    nel corpo facciano passare come follow-up un normale risultato o recap.
    """
    title_probe = normalize_for_check(title or "")
    padded_title = f" {title_probe} "
    if not title_probe:
        return False

    has_advancement = any(_probe_has_phrase(padded_title, term) for term in V807_FOLLOWUP_ADVANCEMENT_TERMS)
    if not has_advancement:
        return False

    # Deve esserci almeno un'entita/evento wrestling rilevante; altrimenti e' troppo generico.
    context_terms = [
        "asuka", "iyo sky", "kairi sane", "wwe", "aew", "nxt", "raw", "smackdown",
        "backlash", "collision", "dynamite", "darby allin", "kazuchika okada",
        "mjf", "jack perry", "mark davis", "danhausen", "minihausen",
    ]
    return any(_probe_has_phrase(padded_title, term) for term in context_terms)


def v807_followup_advancement_key(title="", text="", url=""):
    if not v807_is_followup_advancement_title(title, text):
        return ""
    entities = v7915_primary_entities(title, text)
    ctx = v7915_detect_context(title, text, url)
    title_probe = normalize_for_check(title or "")
    if any(t in title_probe for t in ["backstage reaction", "backstage reactions"]):
        angle = "backstage_reaction"
    elif any(t in title_probe for t in ["semi retired", "semi-retired", "retirement", "retired"]):
        angle = "career_retirement_status"
    elif "future" in title_probe or "uncertainty" in title_probe or "status" in title_probe:
        angle = "career_future_status"
    else:
        angle = "followup_advancement"

    parts = []
    if entities:
        parts.extend(entities[:2])
    else:
        parts.append(v7915_slug(title)[:40])
    parts.append(angle)
    for c in ctx:
        if c not in parts:
            parts.append(c)
    if len(parts) < 3:
        parts.append("followup")
    return "stable_followup_v807:" + "|".join(parts[:8])[:220]


def v7915_stable_story_key(title="", text="", url=""):
    follow_key = v807_followup_advancement_key(title, text, url)
    if follow_key:
        return follow_key
    return _ORIG_V807_v7915_stable_story_key(title, text, url)


def build_story_signature_v71(title, text, url=""):
    # Usa prima la signature originale di v80.6. Se il titolo e' un follow-up
    # advancement, sostituiamo solo la firma stabile, lasciando il resto intatto.
    data = _ORIG_V807_build_story_signature_v71(title, text, url)
    follow_key = v807_followup_advancement_key(title, text, url)
    if follow_key:
        data = dict(data or {})
        data["signature"] = follow_key
        data["stable_signature_v807"] = True
        data["followup_advancement_v807"] = True
        data["followup_reason_v807"] = "same entity/event but new career/backstage/future angle"
    return data


def semantic_duplicate_check_v71(title, text, url, history=None, seen_story_signatures=None, existing_items=None):
    # Lascia passare i follow-up advancement anche se il vecchio layer li avrebbe
    # scambiati per rewrite della stessa storia basandosi su wrestler/evento.
    result = _ORIG_V807_semantic_duplicate_check_v71(
        title, text, url,
        history=history,
        seen_story_signatures=seen_story_signatures,
        existing_items=existing_items,
    )
    if result.get("duplicate") and v807_is_followup_advancement_title(title, text):
        result = dict(result or {})
        result["duplicate"] = False
        result["status"] = "followup_advancement_not_duplicate_v807"
        result["dedupe_override_v807"] = True
        result["reason_v807"] = "same wrestler/event allowed because title introduces backstage/future/career-status angle"
    return result




# =========================
# v80.9: inline-link embed fix + semantic career-status translation guardrail
# =========================
# Scope:
# 1) Fix Tiffany/Paige class of bugs: social/video links inside normal prose must stay inline links,
#    not become standalone oEmbed blocks. Only true standalone embed contexts become oEmbed blocks.
# 2) Add a semantic validation/repair layer for career/status wording after translation/post-edit,
#    so terms like retirement/released/cleared/status are protected as wrestling concepts instead
#    of relying on one-off string replacements.

BOT_VERSION = "v80_9_inline_embed_and_career_status_guardrail"
BOT_VERSION_FULL = f"{BOT_VERSION} ({GIT_SHA_SHORT})"


def v809_node_visible_text_without_links(node):
    try:
        clone = BeautifulSoup(str(node), "html.parser")
        for a in clone.find_all("a"):
            a.decompose()
        return sanitize_text(clone.get_text(" ", strip=True))
    except Exception:
        return ""


def v809_anchor_is_standalone_embed_context(node, anchor):
    """Return True only when a social/video anchor is actually being used as an embed block.

    The key rule: a link inside a normal sentence is editorial context and must remain inline.
    It becomes an embed only if the surrounding node is basically just that link or a known
    'view this post/video' wrapper.
    """
    if not node or not anchor:
        return False
    href = normalize_embed_url(anchor.get("href", ""))
    if not is_valid_embed_url(href):
        return False

    # If the node itself is a known raw/embed wrapper, accept it.
    classes = " ".join(node.get("class", []))
    if node.name in {"iframe", "amp-twitter", "amp-instagram"}:
        return True
    if "twitter-tweet" in classes or "instagram-media" in classes or "tiktok-embed" in classes:
        return True

    links = node.find_all("a", href=True) if hasattr(node, "find_all") else []
    if len(links) != 1:
        return False

    full_text = sanitize_text(node.get_text(" ", strip=True))
    link_text = sanitize_text(anchor.get_text(" ", strip=True))
    outside_text = v809_node_visible_text_without_links(node)
    full_low = normalize_for_check(full_text)
    link_low = normalize_for_check(link_text)
    outside_low = normalize_for_check(outside_text)

    # Pure URL paragraph, or an anchor whose visible text is just the URL.
    if V80_SOCIAL_OEMBED_RE.fullmatch(full_text or ""):
        return True
    if link_text and V80_SOCIAL_OEMBED_RE.fullmatch(link_text):
        return True

    # Typical embed wrappers generated by sites/plugins.
    embed_labels = [
        "view this post", "view this post on instagram", "guarda il post", "guarda questo post",
        "watch this video", "watch on youtube", "guarda il video", "guarda su youtube",
        "view on tiktok", "watch on tiktok", "guarda su tiktok",
        "twitter", "instagram", "tiktok", "youtube",
    ]
    if full_low and len(full_low) <= 90 and any(label in full_low for label in embed_labels):
        # Accept only when there is no meaningful prose outside the link.
        if not outside_low or len(outside_low) <= 24:
            return True

    # If the text outside the anchor contains real prose, it is an inline source/link.
    # Examples: "... al Battleground Podcast" or "... su TikTok".
    if outside_low and len(outside_low) > 24:
        return False

    # If the node is effectively just the link label, allow embed only for generic labels,
    # not named editorial sources such as "Battleground Podcast".
    generic_labels = {"instagram", "tiktok", "youtube", "x", "twitter", "video", "post", "tweet"}
    if link_low and len(full_low) <= max(len(link_low) + 12, 40):
        return any(g in link_low for g in generic_labels)

    return False


_ORIG_V809_node_social_embed_urls = _node_social_embed_urls

def _node_social_embed_urls(node):
    """v80.9: strict embed extraction.

    Keep raw embed detection, but do not promote ordinary inline social/video anchors to EMBED blocks.
    """
    if not node:
        return []
    embeds = []

    for amp_tw in node.find_all("amp-twitter"):
        tweet_id = amp_tw.get("data-tweetid")
        if tweet_id:
            href = f"https://twitter.com/i/status/{tweet_id}"
            if is_valid_embed_url(href):
                embeds.append(href)

    for amp_ig in node.find_all("amp-instagram"):
        shortcode = amp_ig.get("data-shortcode")
        if shortcode:
            href = f"https://www.instagram.com/p/{shortcode}/"
            if is_valid_embed_url(href):
                embeds.append(href)

    for blockquote in node.find_all("blockquote"):
        classes = " ".join(blockquote.get("class", []))
        if "twitter-tweet" in classes or "instagram-media" in classes or "tiktok-embed" in classes:
            for a in blockquote.find_all("a", href=True):
                href = normalize_embed_url(a["href"])
                if is_valid_embed_url(href):
                    embeds.append(href)

    for iframe in node.find_all("iframe", src=True):
        src = iframe["src"]
        fb_href = extract_facebook_url_from_iframe(src)
        if fb_href:
            fb_href = normalize_embed_url(fb_href)
            if is_valid_embed_url(fb_href):
                embeds.append(fb_href)
                continue
        src = normalize_embed_url(src)
        if is_valid_embed_url(src):
            embeds.append(src)

    # Anchor handling is now conservative: standalone embed wrapper only.
    for a in node.find_all("a", href=True):
        href = normalize_embed_url(a.get("href", ""))
        if is_valid_embed_url(href) and v809_anchor_is_standalone_embed_context(node, a):
            embeds.append(href)

    return dedupe_preserve_order(embeds)


V809_CAREER_STATUS_SOURCE_TERMS = [
    "retirement", "retire", "retired", "semi-retired", "semi retired", "retires",
    "release", "released", "roster cuts", "future", "status", "contract", "free agent",
    "cleared", "not cleared", "injury status", "medical status", "career status",
]

V809_CAREER_STATUS_BAD_IT_TERMS = [
    "pensione", "pensionamento", "pensionata", "pensionato",
    "rilascio", "rilasciata", "rilasciato", "rilasciati", "rilasciate",
    "stato in wwe", "stato della wwe", "pulita dal punto di vista medico", "pulito dal punto di vista medico",
]


def v809_source_has_career_status_concept(source_title="", source_text=""):
    probe = normalize_for_check(f"{source_title} {(source_text or '')[:4000]}")
    return any(term in probe for term in V809_CAREER_STATUS_SOURCE_TERMS)


def v809_extract_career_status_source_excerpt(source_title="", source_text=""):
    raw = f"{source_title}\n{source_text or ''}"
    # Keep this cheap: return title plus sentences containing relevant source terms.
    pieces = []
    for sent in re.split(r"(?<=[.!?])\s+|\n+", raw):
        low = normalize_for_check(sent)
        if any(term in low for term in V809_CAREER_STATUS_SOURCE_TERMS):
            clean = sanitize_text(sent)
            if clean and clean not in pieces:
                pieces.append(clean)
        if len(" ".join(pieces)) > 1200:
            break
    return "\n".join(pieces[:8])[:1800]


def v809_find_bad_career_status_nodes(html="", source_title="", source_text=""):
    if not html or not v809_source_has_career_status_concept(source_title, source_text):
        return []
    bad = []
    try:
        soup = BeautifulSoup(html, "html.parser")
        for node in soup.find_all(["p", "li", "blockquote"]):
            text = sanitize_text(node.get_text(" ", strip=True))
            low = normalize_for_check(text)
            if not text:
                continue
            if any(term in low for term in V809_CAREER_STATUS_BAD_IT_TERMS):
                bad.append(text)
        # Fallback on whole text if parsing found nothing but terms exist.
        if not bad:
            full = sanitize_text(soup.get_text(" ", strip=True))
            low = normalize_for_check(full)
            if any(term in low for term in V809_CAREER_STATUS_BAD_IT_TERMS):
                bad.append(full[:500])
    except Exception:
        low = normalize_for_check(html)
        if any(term in low for term in V809_CAREER_STATUS_BAD_IT_TERMS):
            bad.append(sanitize_text(BeautifulSoup(html, "html.parser").get_text(" ", strip=True))[:500])
    return bad[:6]


def v809_deterministic_career_cleanup_sentence(sentence="", source_excerpt=""):
    """Conservative cleanup for known Italian mistranslation classes.

    This is a safety net after semantic repair, not the primary fix.
    """
    out = sentence or ""
    source_low = normalize_for_check(source_excerpt)
    if any(t in source_low for t in ["retirement", "retire", "retired", "semi retired", "semi-retired"]):
        out = re.sub(r"\bpensione\b", "ritiro", out, flags=re.I)
        out = re.sub(r"\bpensionamento\b", "ritiro", out, flags=re.I)
        out = re.sub(r"\bpensionata\b", "ritirata", out, flags=re.I)
        out = re.sub(r"\bpensionato\b", "ritirato", out, flags=re.I)
        out = re.sub(r"\bla\s+ritiro\b", "il ritiro", out, flags=re.I)
        out = re.sub(r"\bil\s+ritiro\s+non\s+e\s+(?:affatto\s+)?(?:la\s+)?situazione\b", "il ritiro non sarebbe in programma", out, flags=re.I)
        out = re.sub(r"\bil\s+ritiro\s+non\s+è\s+(?:affatto\s+)?(?:la\s+)?situazione\b", "il ritiro non sarebbe in programma", out, flags=re.I)
    if any(t in source_low for t in ["release", "released", "roster cuts"]):
        out = re.sub(r"\brilascio\b", "licenziamento", out, flags=re.I)
        out = re.sub(r"\brilasciata\b", "licenziata", out, flags=re.I)
        out = re.sub(r"\brilasciato\b", "licenziato", out, flags=re.I)
        out = re.sub(r"\brilasciati\b", "licenziati", out, flags=re.I)
        out = re.sub(r"\brilasciate\b", "licenziate", out, flags=re.I)
    return out


def v809_repair_career_status_sentence(sentence="", source_title="", source_text=""):
    source_excerpt = v809_extract_career_status_source_excerpt(source_title, source_text)
    if not sentence or not source_excerpt:
        return v809_deterministic_career_cleanup_sentence(sentence, source_excerpt)
    prompt = f"""
Sei un editor italiano di wrestling. Devi riparare UNA SOLA frase italiana che contiene probabilmente un errore su status/carriera.
Restituisci SOLO JSON valido in una riga: {{"frase":"..."}}

REGOLE:
- Mantieni lo stesso fatto dell'originale inglese.
- Nel wrestling, retirement = ritiro/ritirarsi, mai pensione/pensionamento.
- released/release = licenziato, svincolato o addio alla compagnia secondo contesto, mai rilasciato/rilascio.
- cleared/not cleared = autorizzato/non autorizzato a lottare, non "pulito".
- Non aggiungere informazioni, non cambiare nomi, eventi, date o rapporti tra soggetti.
- Riscrivi solo la frase data, in italiano naturale e giornalistico.

TITOLO ORIGINALE:
{source_title}

ESTRATTO ORIGINALE RILEVANTE:
{source_excerpt}

FRASE ITALIANA DA RIPARARE:
{sentence}
""".strip()
    try:
        data, used_model = generate_and_parse_json(prompt)
        repaired = sanitize_text(str(data.get("frase", "") or ""))
        if repaired and len(repaired) >= 12:
            repaired = v809_deterministic_career_cleanup_sentence(repaired, source_excerpt)
            print(f"[CAREER v80.9] Repair frase career/status con {used_model}")
            return repaired
    except Exception as e:
        print(f"[CAREER v80.9] Repair AI fallito, uso cleanup conservativo: {e}")
    return v809_deterministic_career_cleanup_sentence(sentence, source_excerpt)


def v809_repair_career_status_html(html="", source_title="", source_text=""):
    if not html or not v809_source_has_career_status_concept(source_title, source_text):
        return html
    bad_sentences = v809_find_bad_career_status_nodes(html, source_title, source_text)
    if not bad_sentences:
        return html
    out = html
    for bad in bad_sentences:
        repaired = v809_repair_career_status_sentence(bad, source_title, source_text)
        if repaired and repaired != bad:
            out = out.replace(bad, repaired)
    out = fix_mojibake(out)
    return out


_ORIG_V809_build_protected_facts_for_prompt = build_protected_facts_for_prompt

def build_protected_facts_for_prompt(source_title, source_text):
    facts = list(_ORIG_V809_build_protected_facts_for_prompt(source_title, source_text) or [])
    if v809_source_has_career_status_concept(source_title, source_text):
        probe = normalize_for_check(f"{source_title} {(source_text or '')[:3000]}")
        if any(t in probe for t in ["retirement", "retire", "retired", "semi retired", "semi-retired"]):
            facts.append("Career status: retirement/retired/semi-retired nel wrestling va reso come ritiro/ritirarsi/semi-ritiro, mai pensione o pensionamento.")
        if any(t in probe for t in ["release", "released", "roster cuts"]):
            facts.append("Roster status: release/released nel wrestling va reso come licenziamento, svincolo o addio alla compagnia secondo contesto, mai rilascio/rilasciato.")
        if any(t in probe for t in ["cleared", "not cleared"]):
            facts.append("Medical status: cleared/not cleared va reso come autorizzato/non autorizzato a lottare, non pulito/non pulito.")
        if any(t in probe for t in ["status", "future", "contract", "free agent"]):
            facts.append("Status/future/contract: preservare il senso editoriale sul futuro o sullo status del wrestler senza calchi letterali innaturali.")
    return dedupe_preserve_order(facts)[:18]


_ORIG_V809_v79_editorial_post_edit = v79_editorial_post_edit

def v79_editorial_post_edit(news_data, source_title="", source_text="", source_url=""):
    news_data = _ORIG_V809_v79_editorial_post_edit(news_data, source_title, source_text, source_url)
