    if key not in _V851_SCORE_LOG_KEYS:
        _V851_SCORE_LOG_KEYS.add(key)
        return _ORIG_V851_calculate_importance_score(title, text, url)
    try:
        import contextlib, io
        with contextlib.redirect_stdout(io.StringIO()):
            return _ORIG_V851_calculate_importance_score(title, text, url)
    except Exception:
        return _ORIG_V851_calculate_importance_score(title, text, url)


